const fs = require('fs');

const config = JSON.parse(fs.readFileSync('config.json', 'utf8'));

const out = {
  port: config.port !== undefined ? config.port : 3000,
  host: config.host !== undefined ? config.host : '127.0.0.1',
  ...config,
};

fs.writeFileSync('config.out.json', JSON.stringify(out, null, 2) + '\n');

